const $=id=>document.getElementById(id), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=n=>`<svg class="icon" aria-hidden="true"><use href="assets/icons.svg?v=0408-r2#${n}"/></svg>`;
const kinds={model:[icon('image'),'動態模型'],activity:[icon('layout'),'互動模組'],camera:[icon('image'),'鏡頭控制'],repeat:[icon('branch'),'重複執行'],repeatEnd:[icon('branch'),'重複結束'],video:[icon('play'),'影片播放'],background:[icon('image'),'背景切換'],dialogue:[icon('chat'),'角色對話'],choice:[icon('branch'),'選項分支'],music:[icon('music'),'音樂播放'],end:[icon('end'),'故事結束']};
Object.assign(kinds,{audioStop:[icon('music'),'停止音訊'],section:[icon('layout'),'區段'],character:[icon('person'),'角色演出'],variable:[icon('edit'),'變數操作'],condition:[icon('branch'),'條件分歧'],jump:[icon('right'),'劇情跳轉'],input:[icon('edit'),'玩家輸入'],effect:[icon('image'),'畫面效果'],sound:[icon('music'),'音效播放'],wait:[icon('target'),'等待'],intro:[icon('file'),'過場標題'],fade:[icon('image'),'淡入淡出'],animation:[icon('image'),'動畫'],avatar:[icon('person'),'角色頭像'],textbox:[icon('layout'),'對話框顯示'],unlockCg:[icon('image'),'解鎖 CG'],unlockBgm:[icon('music'),'解鎖音樂'],minigame:[icon('layout'),'小遊戲'],cg:[icon('image'),'CG 回憶']});
