const defaults=()=>({title:'春日物語',version:1,images:[],chapters:[{id:uid(),title:'序章　相遇的放學後',events:[{id:uid(),type:'background',text:'教室_放學後',scene:'classroom'},{id:uid(),type:'dialogue',name:'小春',text:'今天也一起回家嗎？',speed:35},{id:uid(),type:'dialogue',name:'男主角',text:'嗯？可以啊。怎麼今天突然這樣問？',speed:35},{id:uid(),type:'dialogue',name:'小春',text:'因為……今天的夕陽很漂亮，想和你一起看。',speed:35},{id:uid(),type:'choice',text:'要不要一起回家？',options:[{text:'好啊，一起回去吧。',target:5},{text:'我還有點事，下次好嗎？',target:7}]},{id:uid(),type:'dialogue',name:'小春',text:'那我們走吧！我知道一條開滿櫻花的小路。',speed:35},{id:uid(),type:'end',text:'夕陽將兩人的影子拉得好長。這個春天，故事才剛開始。'},{id:uid(),type:'dialogue',name:'小春',text:'好，那說好了喔。明天，換我等你。',speed:35},{id:uid(),type:'end',text:'還有明天，還有無數個等待相遇的春日。'}]},{id:uid(),title:'第一章　櫻花下的約定',events:[{id:uid(),type:'dialogue',name:'小春',text:'你還記得，我們第一次見面的地方嗎？',speed:35}]}]});
