function field(label,html,top=false){return `<div class="field ${top?'top':''}"><label>${label}</label>${html}</div>`}
function input(key,value,type='text'){return `<input ${key==='character'?'list="characterTargets"':''} data-key="${key}" aria-label="${key==='name'?'角色名稱':'事件內容'}" type="${type}" value="${esc(value)}">`}
function renderProperties(){const e=event();if(!e){$('propertyContent').innerHTML='<p class="hint">新增一個事件，開始寫故事。</p>';return}let fields='';if(e.type==='dialogue')fields+=field('角色名稱',input('name',e.name));fields+=field(e.type==='dialogue'?'對話內容':'事件內容',`<textarea data-key="text" aria-label="事件內容">${esc(e.text)}</textarea>`,true);if(e.type==='background')fields+=field('背景素材',`<select data-key="scene" aria-label="背景素材"><option value="classroom" ${e.scene==='classroom'?'selected':''}>教室放學後</option><option value="campus" ${e.scene==='campus'?'selected':''}>暖色回憶</option><option value="night" ${e.scene==='night'?'selected':''}>夜色教室</option>${project.images.map(img=>`<option value="${esc(img.id)}" ${img.id===e.scene?'selected':''}>${esc(img.name)}</option>`).join('')}</select>`);if(e.type==='background')fields+=`<label class="checkbox"><input type="checkbox" data-key="clearActors" ${e.clearActors!==false?'checked':''}>切換時清除所有立繪</label>`;if(e.type==='dialogue')fields+=field('文字速度',`<div class="range-control event-speed" style="--range-progress:${((e.speed||35)-5)/75*100}%"><div class="range-caption"><output>${e.speed||35} 字／秒</output></div><div class="range-inputs"><button type="button" data-range-step="speed" data-delta="-1" aria-label="降低文字速度" ${(e.speed||35)<=5?'disabled':''}>−</button><input type="range" min="5" max="80" step="1" value="${e.speed||35}" data-key="speed" aria-label="文字速度"><button type="button" data-range-step="speed" data-delta="1" aria-label="提高文字速度" ${(e.speed||35)>=80?'disabled':''}>＋</button><input class="range-number" type="number" min="5" max="80" step="1" data-key="speed" value="${e.speed||35}" aria-label="文字速度數值"></div></div>`);if(e.type==='choice'){fields+=`<p class="hint">選擇目的事件，建立故事分支。</p>`;(e.options||[]).forEach((o,i)=>{fields+=field('選項 '+(i+1),`<input data-option="${i}" value="${esc(o.text)}" aria-label="選項 ${i+1}">`);fields+=field('跳至事件',`<select data-target="${i}" aria-label="選項 ${i+1} 目的事件"><option value="" ${o.target==null?'selected':''}>未連接</option>${events().map((v,j)=>`<option value="${j}" ${o.target===j?'selected':''}>${j+1}　${esc(String(v.text||'').slice(0,13))}</option>`).join('')}</select>`)});fields+='<button id="addOption" class="pink-text">＋ 新增選項</button>'}if(e.type==='music')fields+=`<p class="hint">可選擇匯入的音訊或內建鋼琴。</p><button id="hearMusic" class="primary">${icon('music')}預聽和弦</button>`;fields+=extraFields(e);fields+=`<details class="advanced" ${advancedExpanded()?'open':''}><summary class="advanced-title">${icon('chevron-down')}進階設定</summary><label class="checkbox"><input type="checkbox" data-key="wait" ${(['character','animation'].includes(e.type)?e.wait===true:e.wait!==false)?'checked':''}>${['character','animation'].includes(e.type)?'等待動畫完成':'等待玩家點擊後繼續'}</label><label class="checkbox"><input type="checkbox" data-key="showName" ${e.showName!==false?'checked':''}>顯示角色名稱</label></details><div class="property-actions"><button id="moveUp" data-move="-1">${icon('up')}上移</button><button id="moveDown" data-move="1">${icon('down')}下移</button><button id="deleteEvent" class="danger">${icon('delete')}刪除事件</button></div>`;$('propertyContent').innerHTML=`<div class="prop-intro"><span class="symbol">${kinds[e.type][0]}</span><div><b>${kinds[e.type][1]}</b></div></div><div class="prop-fields">${fields}</div>`}
function previewScene(){const state=window.KoiVisual.visualStateAt(project,chapter,selected);const cg=event()?.type==='cg'?project.images.find(x=>x.id===event().image):null;const img=cg||project.images.find(x=>x.id===state.scene);$('sceneArt').className='scene-art '+(img?'':state.scene)+' effect-'+state.effect;$('sceneArt').style.backgroundImage=img?`url("${img.data}")`:'';Object.assign($('sceneArt').style,state.background?.motion&&state.background.motion!=='none'?window.KoiGameUI.motionStyle(state.background):{animationName:'',animationDuration:'',animationIterationCount:'',animationFillMode:'',animationTimingFunction:''},window.KoiWorkspace.backgroundStyle(cg?{}:state.background||{},img,window.KoiGameUI.gameUI(project,$('previewDevice').value==='mobile'?'mobile':'desktop').aspect));let backgroundVideo=$('sceneArt').querySelector('video');const clip=!cg&&project.videos.find(v=>v.id===state.background?.backgroundVideo);if(clip){if(!backgroundVideo){backgroundVideo=document.createElement('video');backgroundVideo.muted=true;backgroundVideo.loop=true;backgroundVideo.playsInline=true;backgroundVideo.style.cssText='position:absolute;inset:0;width:100%;height:100%;object-fit:cover;pointer-events:none';$('sceneArt').append(backgroundVideo)}if(backgroundVideo.dataset.asset!==clip.id){backgroundVideo.dataset.asset=clip.id;backgroundVideo.src=clip.data;try{backgroundVideo.play()?.catch(()=>{})}catch{}}}else backgroundVideo?.remove();$('previewActors').innerHTML=cg?'':Object.entries(state.actors).map(([name,a])=>{const img=project.images.find(x=>x.id===a.image);return img?`<img class="preview-actor" src="${esc(img.data)}" alt="${esc(name)}" style="${Object.entries(window.KoiPlacement.actorStyle(window.KoiGameUI.actorForDevice(a,previewDevice()))).map(([k,v])=>k+':'+v).join(';')}">`:''}).join('')}
function typeText(text,speed,animate){clearInterval(typing);currentText=text;typed=!animate;$('dialogText').textContent=animate?'':text;if(animate){let count=0;typing=setInterval(()=>{$('dialogText').textContent=text.slice(0,++count);if(count>=text.length){clearInterval(typing);typed=true;autoAdvance()}},1000/(speed||35))}}
const textEventTypes=new Set(['dialogue','choice','input','cg','end','intro']);
function previewDialogue(){for(let i=selected;i>=0;i--)if(!events()[i]?.blockDetached&&textEventTypes.has(events()[i]?.type))return events()[i];return null}
function previewDevice(){return window.KoiGameUI.resolveDevice($('previewDevice')?.value||'auto',innerWidth,innerHeight)}
function renderPreview(animate){const e=event(),line=previewDialogue();previewScene();$('choiceOverlay').innerHTML='';$('dialogue').hidden=['video','input','intro','fade'].includes(e?.type)||!line;window.KoiVideoPreview?.render(e?.type==='video'?project.videos.find(a=>a.id===e.video):null,e?.type==='video'?e:null);$('speaker').style.display=line?.showName===false?'none':'';$('speaker').textContent=line?(line.name||(line.type==='end'?'故事結束':'旁白')):'';typeText(window.KoiWorkspace.interpolateText(line?.text||'',project.variables,project.tables),line?.speed,animate&&!!line);if(e?.type==='choice'){$('choiceOverlay').innerHTML=`<div class="choices">${(e.options||[]).map((o,i)=>`<button data-choose="${i}">${esc(o.text)}</button>`).join('')}</div>`}if(e?.type==='input')$('choiceOverlay').innerHTML=`<form class="editor-input-preview"><label>${esc(window.KoiWorkspace.interpolateText(e.text||'',project.variables,project.tables))}<input aria-label="玩家輸入" placeholder="請輸入…" maxlength="80"></label><button type="submit">確定</button></form>`;if(playing&&e?.type==='music')chord();window.KoiGameUI.applyEditorUI(project,line,previewDevice())}
function autoAdvance(){if(playing&&event()?.wait===false&&event()?.type!=='choice'&&event()?.type!=='end')setTimeout(()=>{if(playing&&event()?.wait===false)step(1)},1000)}
function select(i,append=false,editingOnly=false){if(!editingOnly&&!append)selectedCards=new Set();const id=events()[i]?.id;if(id&&!editingOnly){if(append&&selectedCards.has(id))selectedCards.delete(id);else selectedCards.add(id)}playing=false;$('exitPlay').hidden=true;$('playStatus').textContent='編輯預覽';selected=i;render();if(innerWidth<=900&&document.body.dataset.panel==='properties')showPanel('workspace')}
function step(n){if(playing&&!typed){clearInterval(typing);$('dialogText').textContent=currentText;typed=true;autoAdvance();return}if(playing&&event()?.type==='choice'&&n>0)return;if(playing&&event()?.type==='end'&&n>0){stop();toast('試玩結束，回到編輯模式');return}selected=Math.max(0,Math.min(events().length-1,selected+n));renderRows();renderProperties();renderPreview(playing);if(mode==='flow')renderFlow();window.KoiTabs?.sync(project,{chapter,selected,mode})}
function play(){ensureProject();stop();window.KoiPlayer.mount(project,{start:{chapter,index:selected},previewDevice:$('previewDevice').value})}
function stop(){playing=false;clearInterval(typing);$('exitPlay').hidden=true;$('playStatus').textContent='編輯預覽';renderPreview(false)}
function setMode(m){if(m==='code')window.KoiWorkspace.ensureChapterProgram(project,project.chapters[chapter].id);if(window.KoiTabs&&!window.KoiTabs.isStory()){const c=project.chapters[chapter]||project.chapters[0];window.KoiTabs.openStory(c.id,c.title,{selected,mode:m});return}const changed=mode!==m;mode=m;document.body.classList.toggle('flow-mode',m==='flow');document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));$('eventList').hidden=m!=='event';$('flowEditor').hidden=m!=='flow';$('blockEditor').hidden=m!=='blocks';$('codeEditor').hidden=m!=='code';document.body.classList.toggle('code-mode',m==='code');document.body.classList.toggle('blocks-mode',m==='blocks');$('editorTitle').textContent=m==='code'?'程式編輯':m==='blocks'?'積木編輯':m==='flow'?'故事流程圖':'事件列表';if(innerWidth<=900&&changed&&!previewChoice())togglePreview(m==='event',false);showPanel('workspace');renderRows();window.KoiTabs?.sync(project,{chapter,selected,mode});window.dispatchEvent(new Event('koi-preview-layout'))}
function renderFlow(){renderRows()}
function showPanel(panel){document.body.dataset.panel=panel;window.dispatchEvent(new Event('koi-preview-layout'));document.querySelectorAll('[data-panel]').forEach(v=>v.classList.toggle('active',v.dataset.panel===panel));if(panel==='properties'){setPropertiesClosed(false);renderProperties()}}
function previewChoice(){try{return localStorage.getItem('koi-preview-expanded')}catch{return null}}
function togglePreview(expand,remember=true){document.body.classList.toggle('preview-collapsed',!expand);for(const el of [$('previewViewport'),$('previewSplitter'),document.querySelector('.playbar')])if(el)el.hidden=!expand;if(remember)try{localStorage.setItem('koi-preview-expanded',String(expand))}catch{}$('previewToggle').innerHTML=(expand?'收合預覽':'展開預覽')+icon('chevron-down');$('previewToggle').setAttribute('aria-expanded',String(expand));window.dispatchEvent(new Event('koi-preview-layout'))}
function add(type,text,extra={},layout,defer=false){if(type==='characterExit'){const active=window.KoiVisual.visualStateAt(project,chapter,selected).actors;const key=Object.keys(active).at(-1)||'fig-center';extra={...extra,character:key,position:active[key]?.position||'center',action:'hide',motion:'fadeOut',motionDuration:800,wait:true};type='character';text='角色退場'}if(type==='repeat')return addRepeat(defer);snapshot();if(layout)events().forEach((e,i)=>{if(layout[i])e.pos={...layout[i]}});const e={id:window.KoiWorkspace.createBlockIdAllocator(project)(),type,text:text||(type==='dialogue'?'在這裡寫下你的對白。':type==='choice'?'你會怎麼選擇？':type==='end'?'故事，在這裡暫告一段落。':type==='music'?'春日鋼琴和弦':'教室_放學後'),...extra};if(type==='dialogue'){e.name=extra.name||'小春';e.speed=35}if(type==='choice')e.options=[{text:'選項一',target:Math.min(selected+1,events().length)},{text:'選項二',target:Math.min(selected+1,events().length)}];if(type==='background'&&!e.scene)e.scene='classroom';
if(type==='video')Object.assign(e,{text:text||'影片播放',video:extra.video||project.videos[0]?.id||'',skippable:true,muted:false,volume:100,imageFit:'contain',pauseMusic:true,...extra});
if(type==='activity')Object.assign(e,{text:text||'互動模組',activity:project.extensions?.activities?.[0]?.id||'',resultVariable:'互動分數',...extra});if(type==='camera')Object.assign(e,{text:text||'鏡頭控制',cameraX:50,cameraY:50,cameraZoom:1,cameraDuration:800,cameraShake:0,...extra});if(type==='model')Object.assign(e,{text:text||'動態模型',model:project.extensions?.models?.[0]?.id||'',...extra});if(type==='minigame')Object.assign(e,{text:'小遊戲',game:project.minigames[0]?.id||'',resultVariable:'小遊戲分數'});
if(type==='variable')Object.assign(e,{text:'調整好感度',variable:'好感度',operation:'add',value:1});
if(type==='condition')Object.assign(e,{text:'依好感度分歧',variable:'好感度',operator:'>=',value:1,target:Math.min(selected+2,events().length),elseTarget:Math.min(selected+2,events().length)});
if(type==='jump')Object.assign(e,{text:'跳轉至指定事件',target:0});
if(type==='character')Object.assign(e,{wait:true,replaceMode:'keep'},window.KoiVisual.characterDefaults(project,extra),extra);
if(type==='input')Object.assign(e,{text:'請告訴我你的名字。',variable:'玩家名稱'});
if(type==='effect')Object.assign(e,{text:'畫面效果',effect:'fade'});
if(type==='wait')Object.assign(e,{text:'稍作停留',duration:extra.duration??1});if(type==='intro')Object.assign(e,{text:text||'過場標題',duration:1.5,introFont:36,fontColor:'#ffffff',backgroundColor:'#000000',motion:'fade',...extra});if(type==='fade')Object.assign(e,{text:'淡入淡出',direction:'out',duration:1,...extra});if(type==='animation')Object.assign(e,{text:'動畫',wait:true,target:Object.keys(window.KoiVisual.visualStateAt(project,chapter,selected).actors).at(-1)||'fig-center',motion:'fade',motionDuration:1000,...extra});if(type==='textbox')Object.assign(e,{text:'顯示對話框',visible:true,...extra});
if(type==='cg')Object.assign(e,{text:'值得珍藏的回憶',image:extra.image||project.images[0]?.id||''});
if(type==='audioStop')Object.assign(e,{text:text||'停止音訊',channel:'all',...extra});
if(type==='music'&&!e.audio)e.audio='synth';
if(type==='sound'&&!e.audio)e.audio=project.audio[0]?.id||'';
const at=selected+1;shiftLogicTargets(at,1);events().splice(at,0,e);selected=at;if(!defer){dirty();render();toast('已新增'+kinds[type][1])}return e}
function renderAssets(){ensureProject();const q=$('search').value.toLowerCase();let cards=[];if(library==='backgrounds')cards=[{name:'教室_放學後',scene:'classroom'},{name:'教室_夜色',scene:'night'},{name:'暖色回憶',scene:'campus'},...project.images.map(x=>({name:x.name,scene:x.id,data:x.data,kind:x.kind||'background'}))];if(library==='characters')cards=[...project.characters.map(c=>({name:c.name,symbol:icon('person')})),{name:'小春',symbol:icon('person')},{name:'男主角',symbol:icon('person')}];if(['audio','music','sound'].includes(library))cards=[...(library==='sound'?[]:[{name:'春日鋼琴和弦',symbol:icon('music'),audio:'synth'}]),...project.audio.filter(a=>library==='audio'||window.KoiWorkspace.audioRole(project,a)===library).map(a=>({name:a.name,symbol:icon('music'),audio:a.id}))];if(library==='variables'){$('assets').innerHTML='<button class="manager-open" data-tool-tab="variables">管理初始變數與旗標</button>';return}$('assets').innerHTML=cards.filter(c=>c.name.toLowerCase().includes(q)).map(c=>`<button class="asset" data-kind="${esc(c.kind||'')}" data-audio="${esc(c.audio||'')}" data-asset="${esc(c.name)}" data-scene="${esc(c.scene||'')}">${c.symbol?`<div class="swatch">${c.symbol}</div>`:`<img src="${c.data||'assets/classroom.png'}" alt="${esc(c.name)}" style="${c.scene==='night'?'filter:brightness(.5)':c.scene==='campus'?'filter:sepia(.4)':''}">`}<span class="asset-caption" title="${esc(c.name)}">${esc(c.name)}</span></button>`).join('')}
function chord(){try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume();[261.63,329.63,392,493.88].forEach((f,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain(),t=audioCtx.currentTime+i*.12;o.type='triangle';o.frequency.value=f;g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(.1,t+.02);g.gain.exponentialRampToValueAtTime(.001,t+2);o.connect(g);g.connect(audioCtx.destination);o.start(t);o.stop(t+2)})}catch{toast('此瀏覽器不支援音訊預聽')}}
function modal(title,text){$('modalTitle').textContent=title;$('modalBody').textContent=text;$('modal').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.chapterRename!==undefined){renameChapter(Number(b.dataset.chapterRename));return}if(b?.dataset.chapterDelete!==undefined){deleteChapter(Number(b.dataset.chapterDelete));return}if(b?.dataset.rangeStep){snapshot();event().speed=Math.max(5,Math.min(80,Number(event().speed||35)+Number(b.dataset.delta)));dirty();renderRows();renderProperties();renderPreview(false);return}if(document.querySelector('.koi-player'))return;if(b?.dataset.toolTab)openTools(b.dataset.toolTab);if(b?.dataset.actorX){snapshot();event().position=b.dataset.actorX;event().vertical=b.dataset.actorY;dirty();renderProperties();renderPreview(false)};if(b?.dataset.mode){if(window.KoiTabs&&!window.KoiTabs.isStory())window.KoiTabs.openStory(project.chapters[chapter].id,project.chapters[chapter].title,{selected,mode});setMode(b.dataset.mode)};if(b?.dataset.panel){if(b.dataset.panel==='workspace'&&window.KoiTabs&&!window.KoiTabs.isStory())window.KoiTabs.openStory(project.chapters[chapter].id,project.chapters[chapter].title,{selected,mode});showPanel(b.dataset.panel)};if(b?.dataset.chapter!==undefined){stop();chapter=+b.dataset.chapter;selected=0;if(window.KoiTabs)window.KoiTabs.openStory(project.chapters[chapter].id,project.chapters[chapter].title,{selected,mode});render()}if(b?.dataset.duplicate!==undefined){snapshot();const i=+b.dataset.duplicate,copy=structuredClone(events()[i]);copy.id=uid();delete copy.pos;const at=i+1;copy.options?.forEach(o=>{if((!o.targetChapter||o.targetChapter===project.chapters[chapter].id)&&o.target!=null&&o.target>=at)o.target++});for(const k of ['next','target','elseTarget'])if(copy[k]!=null&&!copy.targetChapter&&Number(copy[k])>=at)copy[k]=Number(copy[k])+1;shiftLogicTargets(at,1);events().splice(at,0,copy);selected=at;dirty();render();return}if(b?.dataset.library){library=b.dataset.library;$('libraryTitle').textContent={backgrounds:'背景圖片',characters:'角色立繪',audio:'音樂與音效',music:'音樂',sound:'音效',variables:'變數與條件'}[library];renderAssets()}if(b?.dataset.asset){if(library==='backgrounds'){if(b.dataset.kind==='character')add('character',b.dataset.asset,{image:b.dataset.scene});else if(b.dataset.kind==='cg')add('cg',b.dataset.asset,{image:b.dataset.scene});else add('background',b.dataset.asset,{scene:b.dataset.scene})}else if(library==='characters')add('dialogue','你好，很高興見到你。',{name:b.dataset.asset});else if(['audio','music','sound'].includes(library))add(library==='sound'?'sound':'music',b.dataset.asset,{audio:b.dataset.audio})}if(b?.dataset.choose!==undefined){selected=Math.max(0,Math.min(events().length-1,event().options[+b.dataset.choose].target));renderRows();renderProperties();renderPreview(true)}if(b?.id==='deleteEvent')deleteEvent(selected);if(b?.dataset.move)reorderEvent(selected,selected+Number(b.dataset.move));if(b?.id==='addOption'){snapshot();event().options.push({text:'新的選項',target:Math.min(selected+1,events().length-1)});dirty();renderProperties();if(mode==='flow')renderFlow()}if(b?.id==='hearMusic')chord()});
$('propertyContent').addEventListener('change',e=>{const t=e.target;if(!t.matches('[data-key],[data-option],[data-target],[data-option-var],[data-option-delta]'))return;snapshot();if(t.dataset.key){event()[t.dataset.key]=['target','elseTarget','next'].includes(t.dataset.key)&&event().type!=='animation'?(t.value===''?null:Number(t.value)):t.type==='checkbox'?t.checked:['range','number'].includes(t.type)?+t.value:t.value}else if(t.dataset.option!==undefined)event().options[+t.dataset.option].text=t.value;else if(t.dataset.target!==undefined)event().options[+t.dataset.target].target=t.value===''?null:+t.value;else if(t.dataset.optionVar!==undefined)event().options[+t.dataset.optionVar].variable=t.value;else event().options[+t.dataset.optionDelta].delta=Number(t.value);if(t.dataset.key==='action'&&event().type==='character'){const exit=window.KoiGameUI.exitMotions;if(event().action==='hide'&&!Object.hasOwn(exit,event().motion))event().motion='fadeOut';if(event().action==='show'&&Object.hasOwn(exit,event().motion))event().motion='none';event().motionLoop=false;}if(t.dataset.key==='speed'){event().speed=Math.max(5,Math.min(80,Math.round(Number(event().speed)||35)));const wrap=t.closest('.range-control');if(wrap){wrap.style.setProperty('--range-progress',((event().speed-5)/75*100)+'%');wrap.querySelector('output').textContent=event().speed+' 字／秒';wrap.querySelectorAll('input').forEach(el=>el.value=event().speed);wrap.querySelectorAll('[data-range-step]').forEach(el=>el.disabled=Number(el.dataset.delta)<0?event().speed<=5:event().speed>=80)}}if(t.dataset.key==='variable'&&event().type==='variable'&&project.variableTypes?.[event().variable]&&project.variableTypes[event().variable]!=='number'){event().operation='set';event().value=project.variableTypes[event().variable]==='boolean'?false:''}dirty();renderRows();renderPreview(false);if(mode==='flow')renderFlow();if(t.type==='range'||['targetChapter','variable','action','character'].includes(t.dataset.key))renderProperties()});
$('propertyContent').addEventListener('input',e=>{const t=e.target;if(t.type==='range'&&t.dataset.key==='speed'){const wrap=t.closest('.range-control');wrap.style.setProperty('--range-progress',((Number(t.value)-5)/75*100)+'%');wrap.querySelector('output').textContent=t.value+' 字／秒';wrap.querySelector('.range-number').value=t.value}if(textEventTypes.has(event()?.type)&&(t.dataset.key==='text'||t.dataset.key==='name')){$('dialogText').textContent=t.dataset.key==='text'?t.value:event().text;if(t.dataset.key==='name')$('speaker').textContent=t.value}});
