if(e.type==='textbox')f+=field('顯示對話框',`<input type="checkbox" data-key="visible" ${e.visible!==false?'checked':''}>`);if(e.type==='intro'){f+=field('過場字級',input('introFont',e.introFont||36,'number'));f+=field('文字顏色',input('fontColor',e.fontColor||'#ffffff'));f+=field('背景顏色',input('backgroundColor',e.backgroundColor||'#000000'))}if(e.type==='animation'){f+=field('動畫目標',input('target',e.target??''));f+=field('動畫動作',selectField('motion',Object.entries(window.KoiGameUI.motions||{none:'無',left:'從左滑入',right:'從右滑入',fade:'淡入',shake:'震動',center:'移至中央'}),e.motion||'none'));f+=field('動畫毫秒',input('motionDuration',e.motionDuration||1000,'number'))}if(e.type==='fade')f+=field('轉場方向',selectField('direction',[['out','漸黑'],['in','漸亮']],e.direction||'out'));if(['fade','intro'].includes(e.type))f+=field('持續秒數',input('duration',e.duration??1,'number'));if(e.type==='wait')f+=field('等待秒數',input('duration',e.duration??1,'number'));
if(e.type==='choice')e.options.forEach((o,i)=>{f+=`<div class="choice-effect"><b>選項 ${i+1} 的數值效果</b><select data-option-var="${i}" aria-label="選項變數"><option value="">不修改</option>${vars.map(([k])=>`<option value="${esc(k)}" ${o.variable===k?'selected':''}>${esc(k)}</option>`).join('')}</select><input type="number" data-option-delta="${i}" value="${Number(o.delta)||0}" aria-label="增減數值"></div>`});
