async function renameChapter(i){const c=project.chapters[i];if(!c)return;const title=await koiPrompt('劇情腳本名稱',c.title);if(!title?.trim())return;snapshot();c.title=title.trim().slice(0,100);dirty();render()}
async function deleteChapter(i){const c=project.chapters[i];if(!c)return;if(project.chapters.length===1){toast('至少保留一個劇情腳本');return}const refs=project.chapters.flatMap(ch=>ch.events.filter(e=>e.targetChapter===c.id));if(!await koiConfirm('刪除劇情腳本「'+c.title+'」及其中 '+c.events.length+' 個事件？'+(refs.length?'\n另有 '+refs.length+' 個跨腳本跳轉會取消連接。':'')+'\n可使用復原還原。'))return;const current=project.chapters[chapter].id;snapshot();project.chapters.splice(i,1);for(const ch of project.chapters){if(ch.nextChapter===c.id)ch.nextChapter=null}for(const ch of project.chapters)for(const e of ch.events){if(e.targetChapter===c.id){e.targetChapter='';e.target=null}for(const o of e.options||[])if(o.targetChapter===c.id){delete o.targetChapter;o.target=null}}chapter=Math.max(0,project.chapters.findIndex(c=>c.id===current));selected=0;selectedCards.clear();dirty();render()}
function copySelectedCards(){const ids=[...selectedCards].filter(id=>events().some(e=>e.id===id));if(!ids.length&&event())ids.push(event().id);if(!ids.length)return;cardClipboard=window.KoiWorkspace.copyCards(project,chapter,ids);const ps=window.KoiWorkspace.positions(events());cardClipboard.events.forEach((e,i)=>{if(!e.pos)e.pos={...ps[cardClipboard.indices[i]]}});cardPasteCount=0;if(navigator.clipboard?.writeText)navigator.clipboard.writeText(JSON.stringify(cardClipboard)).catch(()=>{});toast('已複製 '+cardClipboard.events.length+' 張卡片')}
function pasteSelectedCards(){if(!cardClipboard){toast('請先複製流程卡片');return}if(window.KoiWorkspace.inspectBlocks(events()).length||window.KoiWorkspace.inspectBlocks(cardClipboard.events).length){toast('積木結構無效，請先修正事件 ID 與重複積木配對');return} snapshot();const ps=window.KoiWorkspace.positions(events());events().forEach((e,i)=>{if(!e.pos)e.pos={...ps[i]}});const copies=window.KoiWorkspace.pasteCards(project,chapter,selected,{...cardClipboard,events:cardClipboard.events.map(e=>({...e,pos:e.pos?{x:e.pos.x+40*cardPasteCount,y:e.pos.y+40*cardPasteCount}:undefined}))});if(!copies.length){history.pop();return}cardPasteCount++;selected=events().findIndex(e=>e.id===copies[0].id);selectedCards=new Set(copies.map(e=>e.id));dirty();render();toast('已貼上 '+copies.length+' 張卡片')}
document.addEventListener('keydown',e=>{if(!(e.ctrlKey||e.metaKey)||e.altKey||e.target.closest('input,textarea,select,[contenteditable=true]')||!['event','flow','blocks'].includes(mode)||window.KoiTabs&&!window.KoiTabs.isStory()||document.querySelector('.koi-player'))return;const key=e.key.toLowerCase();if(!['a','c','v','x'].includes(key))return;e.preventDefault();if(key==='a'){selectedCards=new Set(events().map(e=>e.id));renderRows();toast('已選取 '+selectedCards.size+' 張卡片')}if(key==='c')copySelectedCards();if(key==='x'){copySelectedCards();deleteSelectedCards()}if(key==='v')pasteSelectedCards()});
