async function deleteSelectedCards(){const projectId=project.id,chapterId=project.chapters[chapter]?.id;const ids=selectedCards.size?[...selectedCards]:event()?[event().id]:[];if(!ids.length||!await koiConfirm('刪除選取的 '+ids.length+' 個事件？選取重複積木會刪除整組內容。可使用復原還原。'+(()=>{const refs=window.KoiWorkspace.eventReferencesTo(project,chapterId,ids);return refs.length?'\n參照風險：'+refs.slice(0,8).map(r=>r.label+(r.crossChapter?'（跨章節）':'')).join('、')+'。刪除後會重新連接或取消目的。':''})()))return;if(project.id!==projectId||project.chapters[chapter]?.id!==chapterId){toast('專案或章節已切換，已取消批次刪除');return}if(mode==='blocks')window.KoiBlockFeedback?.('delete',project.editorSettings?.blockSounds!==false);snapshot();window.KoiWorkspace.deleteCards(project,chapter,ids);selectedCards.clear();selected=Math.max(0,Math.min(selected,events().length-1));dirty();render()}

async function createProject(template,experimental=false){if(projectSwitchBusy)return;await window.KoiReady;
 if(experimental){if(typeof window.showSaveFilePicker!=='function'){toast('此環境缺少串流備份的檔案選擇器，不能建立實驗大容量專案。');return}const c=await window.KoiStorage.storageEstimate();if(c.browserAvailable===null||c.browserAvailable<5000000000){toast('建立實驗專案需要至少 5,000 MB 的瀏覽器估計可用額度；目前專案未變更。');return}if(!await koiConfirm('另建空白的大容量測試專案？4～5 GB 瀏覽器壓力測試尚未完成，僅供可丟棄素材測試。原專案會先儲存並保留；請使用 .koib 串流備份。'))return}
const next=template?{id:uid(),title:template.title,chapters:template.chapters,images:[],audio:[],editorSettings:{...project.editorSettings}}:{id:uid(),title:'未命名的故事',images:[],audio:[],editorSettings:{...project.editorSettings},chapters:[{id:uid(),title:'新的劇情腳本',events:[{id:uid(),type:'dialogue',name:'旁白',text:'在這裡開始新的故事。'}]}]};if(experimental){next.id='experimental-5gb-'+next.id;next.title='大容量實驗測試專案';next.storagePolicy={version:1,mode:'experimental-5gb',testProject:true};next.editorSettings={...next.editorSettings,reporterBlocks:[]}}next.createdAt=Date.now();return switchProject(null,next)}
async function switchProject(id,next){if(projectSwitchBusy||id===project.id)return;projectSwitchBusy=true;clearTimeout(autoSaveTimer);try{await window.KoiStorage.saveProject(project);const loaded=next||await window.KoiStorage.loadProject(id);if(!loaded)throw Error('找不到專案');await window.KoiStorage.saveProject(loaded);stop();project=loaded;ensureProject();chapter=0;selected=0;history=[];future=[];selectedCards.clear();projectRegistry=await window.KoiStorage.listProjects();window.KoiTabs.reset(project);render();renderAssets();renderProjectHub();toast('已開啟專案：'+project.title);return project}catch(e){toast(e.message)}finally{projectSwitchBusy=false}}
async function renameStoredProject(id){if(projectSwitchBusy)return;const item=projectRegistry.find(p=>p.id===id)||project;const name=await koiPrompt('專案名稱',item.title);if(!name?.trim())return;const title=name.trim().slice(0,100);try{if(id===project.id){snapshot();project.title=title;dirty();await save(true)}else await window.KoiStorage.renameProject(id,title);projectRegistry=await window.KoiStorage.listProjects();renderProjectHub();render()}catch(e){toast(e.message)}}
async function duplicateStoredProject(id){if(projectSwitchBusy)return;try{if(id===project.id)await save(true);const original=await window.KoiStorage.loadProject(id);if(!original)throw Error('找不到專案');const copy=JSON.parse(JSON.stringify(original));copy.id=(window.KoiStorage.isLargeProject(original)?'experimental-5gb-':'')+uid();copy.title=original.title+' 副本';copy.createdAt=Date.now();await switchProject(null,copy)}catch(e){toast(e.message)}}
async function deleteStoredProject(id){if(projectSwitchBusy)return;const item=projectRegistry.find(p=>p.id===id)||project;if(!await koiConfirm('刪除專案「'+item.title+'」與其中的劇情、素材？此操作無法復原，請先匯出備份。'))return;try{if(id===project.id){const other=projectRegistry.find(p=>p.id!==id);if(other){if(!await switchProject(other.id))return}else{if(!await createProject())return}}await window.KoiStorage.deleteProject(id);projectRegistry=await window.KoiStorage.listProjects();renderProjectHub();toast('已刪除專案')}catch(e){toast(e.message)}}
function renderProjectHub(){const bar=$('projectTabBar');if(!bar)return;const current=projectRegistry.find(p=>p.id===project.id);if(current)current.title=project.title;else projectRegistry.push({id:project.id,title:project.title});const home=$('projectHomePage');if(home)renderProjectHome(home);bar.innerHTML='<div id="projectMenu" class="project-menu" role="menu" hidden>'+projectRegistry.map(p=>'<button role="menuitemradio" aria-checked="'+(p.id===project.id)+'" data-project-switch="'+esc(p.id)+'" title="'+esc(p.title)+'">'+esc(p.title)+'</button>').join('')+'</div>';bar.querySelectorAll('[data-project-switch]').forEach(b=>b.onclick=()=>{bar.querySelector('#projectMenu').hidden=true;$('projectTitle').setAttribute('aria-expanded','false');switchProject(b.dataset.projectSwitch)});bar.querySelector('#projectMenu').onkeydown=e=>{const buttons=[...bar.querySelectorAll('[data-project-switch]')],i=buttons.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus()}if(e.key==='Escape'){$('projectMenu').hidden=true;$('projectTitle').setAttribute('aria-expanded','false');$('projectTitle').focus()}};$('projectTitle').setAttribute('aria-haspopup','menu');$('projectTitle').setAttribute('aria-expanded','false');const body=$('projectTreeBody'),tree=body.parentElement,root=$('toggleProjectTree');root.remove();body.remove();tree.innerHTML='';for(const p of projectRegistry){const row=document.createElement('div');row.className='project-root-row';const b=p.id===project.id?root:document.createElement('button');if(b!==root){b.className='other-project-root';b.textContent=p.title;b.title=p.title;b.onclick=()=>switchProject(p.id)}row.append(b);for(const [name,label,run]of [['edit','重新命名',renameStoredProject],['copy','複製',duplicateStoredProject],['delete','刪除',deleteStoredProject]]){const action=document.createElement('button');action.className='project-root-action';action.dataset.projectAction=name;action.dataset.projectId=p.id;action.setAttribute('aria-label',label+'專案 '+p.title);action.title=label+'專案';action.innerHTML=icon(name);action.onclick=()=>run(p.id);row.append(action)}tree.append(row);if(p.id===project.id)tree.append(body)}}
window.KoiReady=window.KoiReady.then(async()=>{if(!projectReady)return;projectRegistry=await window.KoiStorage.listProjects();const nav=document.createElement('div');nav.id='projectTabBar';nav.className='project-switcher';nav.setAttribute('aria-label','目前專案');const location=document.createElement('div');location.className='project-location';document.querySelector('.brand').append(location);location.append(document.querySelector('.beta'),$('projectTitle'),nav);renderProjectHub()});
(()=>{const header=$('resources').querySelector('.panel-head'),button=document.createElement('button'),restore=document.createElement('button');button.id='collapseResources';button.title='收起左側欄';button.setAttribute('aria-label','收起左側欄');button.innerHTML=icon('chevron-down');header.insertBefore(button,$('upload'));restore.id='restoreResources';restore.title='展開專案資源';restore.setAttribute('aria-label','展開專案資源');restore.innerHTML=icon('chevron-down');document.body.append(restore);const set=closed=>{document.body.classList.toggle('resources-closed',closed);localStorage.setItem('koi-sidebar-closed',String(closed));if(!closed)showPanel(innerWidth<=900?'resources':'workspace');window.dispatchEvent(new Event('koi-preview-layout'))};button.onclick=()=>set(true);restore.onclick=()=>set(false);if(localStorage.getItem('koi-sidebar-closed')==='true')set(true);document.querySelector('.mobile-tabs [data-panel=resources]')?.addEventListener('click',()=>set(false))})();

