(()=>{const button=$('closeProperties');button.innerHTML=icon('chevron-down');button.title='收起事件屬性';button.setAttribute('aria-label','收起事件屬性');const restore=document.createElement('button');restore.id='restoreProperties';restore.title='展開事件屬性';restore.setAttribute('aria-label','展開事件屬性');restore.innerHTML=icon('chevron-down');restore.onclick=()=>{setPropertiesClosed(false);if(innerWidth<=900)showPanel('properties')};document.body.append(restore);if(localStorage.getItem('koi-properties-closed')==='true')setPropertiesClosed(true);const mini=document.querySelector('.mini-flow');mini.hidden=true;return;const svg=mini.querySelector('svg'),body=document.createElement('div'),toggle=document.createElement('button');body.id='miniFlowBody';svg.before(body);body.append(svg);toggle.id='toggleMiniFlow';toggle.setAttribute('aria-controls','miniFlowBody');toggle.innerHTML=icon('chevron-down');const set=closed=>{body.hidden=closed;toggle.setAttribute('aria-expanded',String(!closed));toggle.setAttribute('aria-label',closed?'展開流程圖概覽':'收起流程圖概覽');toggle.title=closed?'展開流程圖概覽':'收起流程圖概覽';try{localStorage.setItem('koi-mini-flow-closed',String(closed))}catch{}};mini.querySelector('.panel-head').append(toggle);toggle.onclick=()=>set(!body.hidden);set(localStorage.getItem('koi-mini-flow-closed')==='true');$('openFlow').innerHTML=icon('expand');$('openFlow').title='開啟流程圖編輯';$('openFlow').setAttribute('aria-label','開啟流程圖編輯')})();

document.addEventListener('pointerdown',e=>{if(!e.target.closest('#projectTitle,#projectTabBar,#brandHome')){const menu=$('projectMenu');if(menu)menu.hidden=true;$('projectTitle').setAttribute('aria-expanded','false')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){const menu=$('projectMenu');if(menu)menu.hidden=true;$('projectTitle').setAttribute('aria-expanded','false')}});

function addRepeat(defer=false){snapshot();selectedCards.clear();const es=window.KoiWorkspace.repeatEvents(window.KoiWorkspace.createBlockIdAllocator(project)),at=selected+1;shiftLogicTargets(at,es.length);events().splice(at,0,...es);selected=at;if(!defer){dirty();render()}return es[0]}

const topNav=document.createElement('nav');topNav.id='toolNav';topNav.setAttribute('aria-label','編輯工具');for(const[id,label,tab]of [['newProject','新增專案',null],['projectTools','模板編輯','gameDesigner'],['imageTool','圖片編輯','imageEditor'],['assetTool','素材庫','assets'],['variableTool','變數','variables'],['extensionTool','擴充','extensions'],['settingsTool','設定','preferences']]){const b=$(id)||document.createElement('button');b.id=id;b.textContent=label;if(tab)b.onclick=()=>openTools(tab);b.dataset.toolGroup=tab||'new';topNav.append(b)}document.querySelector('.main-tools').before(topNav);

