// Authoring shortcuts stay inside the active story and never intercept text fields or game controls.
document.addEventListener('keydown',e=>{if(e.defaultPrevented||e.repeat||e.target.closest('input,textarea,select,[contenteditable=true]')||document.querySelector('.koi-player,.koi-dialog-shade')||window.KoiTabs&&!window.KoiTabs.isStory())return;const mod=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();if(mod&&['z','y'].includes(key)){e.preventDefault();$(key==='y'||e.shiftKey?'redo':'undo').click();return}if(!mod&&['delete','backspace'].includes(key)&&['event','flow','blocks'].includes(mode)){e.preventDefault();if(selectedCards.size)deleteSelectedCards();else deleteEvent(selected)}});


// The existing project hub is the maker home; navigation never replaces project data.
(()=>{
 const logo=$('brandHome');if(!logo)return;
 let pending=false;
 const focusHome=async(expected=project.id)=>{let listed;try{listed=await window.KoiStorage.listProjects()}catch{toast('專案清單載入失敗，編輯內容已保留');return}if(project.id!==expected||projectSwitchBusy)return;projectRegistry=listed;const current=projectRegistry.find(p=>p.id===project.id);if(current)current.title=project.title;else projectRegistry.push({id:project.id,title:project.title});const opened=window.KoiTabs?.openTool('project-home','專案首頁');if(!opened)return;opened.page.id='projectHomePage';renderProjectHome(opened.page);opened.page.querySelector('[data-current-project]')?.focus()};
 window.KoiReady.then(()=>{logo.disabled=!projectReady;document.documentElement.dataset.brandReady='true'});
 logo.addEventListener('click',async e=>{
  if(e.button!==undefined&&e.button!==0||pending||projectSwitchBusy||!projectReady)return;
  if(!window.KoiTabs)return;
  if(document.querySelector('[data-tab-key="tool:project-home"].active')){await focusHome();return}
  const id=project.id,unsaved=/尚未儲存|儲存中|儲存失敗|Not saved|Saving|Save failed/i.test($('saveState').textContent),draft=(project.programFiles||[]).some(f=>f.syncState?.dirty||f.syncState?.conflict);
  pending=true;
  try{
   if((unsaved||draft)&&!await koiConfirm('目前有尚未儲存的變更或未套用草稿。返回專案首頁？變更與草稿會保留，請記得儲存。'))return;
   if(project.id!==id||projectSwitchBusy){toast('專案已切換，請重新開啟專案首頁');return}
   await focusHome(id);
  }finally{pending=false}
 });
})();


// Use the existing work-tab router and project registry. No second project store.
function renderProjectHome(host){
 if(!host)return;
 host.replaceChildren();const section=document.createElement('section');section.className='project-home';
 const heading=document.createElement('div');heading.className='tools-heading';const title=document.createElement('h2');title.textContent='專案首頁';heading.append(title);
 const body=document.createElement('div');body.className='tools-body';const summary=document.createElement('p');summary.textContent='此裝置共有 '+projectRegistry.length+' 個專案。選擇專案繼續創作。';body.append(summary);
 const actions=document.createElement('div');actions.className='property-actions';
 const resume=()=>{const c=project.chapters[chapter]||project.chapters[0];window.KoiTabs.openStory(c.id,c.title,{selected,mode});showPanel('workspace')};
 for(const[label,run]of [['新增專案',()=>createProject()],['返回目前專案',resume]]){const b=document.createElement('button');b.type='button';b.textContent=label;b.onclick=run;actions.append(b)}body.append(actions);
 for(const item of projectRegistry){const row=document.createElement('div');row.className='project-root-row';const b=document.createElement('button');b.type='button';b.className='other-project-root';b.textContent=item.title;b.setAttribute('data-authored','');b.dataset.openProject=item.id;if(item.id===project.id){b.dataset.currentProject='true';b.setAttribute('aria-current','true');b.title='目前專案'}b.onclick=()=>item.id===project.id?resume():switchProject(item.id);row.append(b);body.append(row)}
 section.append(heading,body);host.append(section);
}
